'use strict';
let curriculum, allWeeks, config, state={schemaVersion:2,week:1,positions:{},codes:{},passed:{},hints:{},seen:{},day:0,task:0}, free=false, busy=false, aborter=null, saveTimer, toastTimer;
const $=id=>document.getElementById(id);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const weekLabel=()=>`WEEK 0${state.week}`;
const day=()=>curriculum.days[state.day];
function weekHeading(){document.title=`IOAI Lab · 第 ${state.week} 周练习`;document.querySelector('.course-label').textContent=`学习路径 / 第 ${state.week} 周`;document.querySelector('.sidebar h1').textContent=curriculum.title;document.querySelector('.side-description').textContent=curriculum.description;document.querySelectorAll('[data-week-link]').forEach(a=>a.classList.toggle('selected',Number(a.dataset.weekLink)===state.week));}
const task=()=>day().tasks[state.task];
const key=()=>free?'free':task().id;
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3000)}
async function persist(){state.schemaVersion=2;state.positions[state.week]={day:state.day,task:state.task};try{localStorage.setItem('ioai-week1',JSON.stringify(state))}catch{};try{const r=await fetch('/api/state',{method:'POST',headers:{'Content-Type':'application/json','X-Lab-Token':config.token},body:JSON.stringify(state)});if(!r.ok)throw Error();$('save-status').textContent='已自动保存到本机'}catch{$('save-status').textContent='本地服务未连接 · 请导出备份'}}
function save(){clearTimeout(saveTimer);saveTimer=setTimeout(persist,350)}
function lines(){$('line-numbers').textContent=Array.from({length:$('editor').value.split('\n').length},(_,i)=>i+1).join('\n')}
function remember(){state.codes[key()]=$('editor').value;try{localStorage.setItem('ioai-week1',JSON.stringify(state))}catch{};save()}
function progress(){const all=curriculum.days.flatMap(d=>d.tasks);let n=all.filter(t=>state.passed[t.id]).length;$('progress-text').textContent=`${n} / ${all.length}`;$('progress-bar').style.width=`${n/all.length*100}%`;$('days').innerHTML=curriculum.days.map((d,i)=>{let done=d.tasks.filter(t=>state.passed[t.id]).length;return `<button class="day-link ${!free&&state.day===i?'active':''}" data-day="${i}" ${!free&&state.day===i?'aria-current="step"':''}><span class="day-number">0${i+1}</span><span class="day-name">${esc(d.short)}<span class="day-sub">${esc(d.tag)} · ${done}/3</span></span>${done===3?'<span class="day-done">✓</span>':''}</button>`}).join('');$('days').querySelectorAll('button').forEach(b=>b.onclick=()=>navigate(Number(b.dataset.day),0));$('free-button').classList.toggle('active',free)}
function resetResult(){$('run-status').textContent='准备就绪';$('result-content').innerHTML='<div class="empty-result"><span>⌁</span><p>写下你的思路，运行看看。</p><small>输出、检查结果和图表会显示在这里</small></div>'}
function render(){const currentUrl=new URL(location.href);currentUrl.searchParams.set('week',state.week);currentUrl.searchParams.set('day',state.day+1);currentUrl.searchParams.set('task',state.task+1);if(free)currentUrl.searchParams.set('free','1');else currentUrl.searchParams.delete('free');history.replaceState(null,'',currentUrl);progress();const d=day(),t=task();$('breadcrumb').innerHTML=free?`${weekLabel()} <span>/</span> 自由练习场`:`${weekLabel()} <span>/</span> ${esc(d.short)}`;$('day-eyebrow').textContent=free?'PLAYGROUND · PYTHON':`DAY 0${state.day+1} · ${d.tag.toUpperCase()}`;$('day-title').textContent=free?'让想法跑起来':d.title;$('day-description').textContent=free?'这里没有标准答案。试一个想法，改一行代码，再观察结果。':d.description;$('day-time').style.display=free?'none':'';$('lesson-summary').textContent=free?'可使用 NumPy、Pandas、Matplotlib 和 scikit-learn；每次运行都是全新的环境。':d.question;$('task-tabs').style.display=free?'none':'flex';$('task-tabs').innerHTML=d.tasks.map((t,i)=>`<button class="task-tab ${i===state.task?'active':''} ${state.passed[t.id]?'passed':''}" role="tab" aria-selected="${i===state.task}" data-task="${i}"><span>${state.passed[t.id]?'✓':i+1}</span>${esc(t.short)}</button>`).join('');$('task-tabs').querySelectorAll('button').forEach(b=>b.onclick=()=>navigate(state.day,Number(b.dataset.task)));$('task-level').textContent=free?'自由探索':`练习 0${state.task+1}`;$('task-title').textContent=free?'你的 Python 草稿纸':t.title;$('task-description').innerHTML=free?'<p>尝试今天学到的方法，也可以把自己的小例子写在这里。输出文字用 <code>print()</code>，显示图表用 <code>plt.show()</code>。</p><div class="free-note">支持读取 scores.csv 和 review.csv。每次运行最长 30 秒。代码在本机 Python 中执行，请只运行你理解的代码。</div>':t.description;$('requirements').innerHTML=free?'':`<div class="mini-label">完成这些步骤</div><ul>${t.requirements.map(x=>`<li>${x}</li>`).join('')}</ul>`;$('data-panel').innerHTML=free?'':(t.data||'');$('help-area').style.display=free?'none':'';$('solution-details').open=false;$('solution-code').textContent=t.solution;$('editor').value=state.codes[key()]??(free?'import numpy as np\nimport pandas as pd\nimport matplotlib.pyplot as plt\n\n# 从这里开始你的实验\nx = np.arange(10)\nprint(x ** 2)\n':t.starter);$('file-name').textContent=free?'playground.py':`${t.id}.py`;$('run-button').textContent=free?'▶ 运行代码':'▶ 运行并检查';$('next-task').style.display=free?'none':'';$('next-task').textContent=state.day===6&&state.task===2?'返回训练中心 →':'下一题 →';renderHints();lines();resetResult()}
function navigate(d,t){if(busy){toast('请先停止当前运行');return}remember();free=false;state.day=d;state.task=t;save();render()}
function renderHints(){if(free)return;const t=task(),n=state.hints[t.id]||0;$('hint-count').textContent=`${n} / ${t.hints.length}`;$('hints').innerHTML=t.hints.slice(0,n).map((h,i)=>`<div class="hint">${i+1}. ${h}</div>`).join('')}
async function run(){if(busy)return;remember();const runKey=key(),wasFree=free;busy=true;aborter=new AbortController();$('run-button').disabled=true;$('stop-button').hidden=false;$('run-status').textContent='正在运行…';$('result-content').innerHTML='<p class="output-text">正在执行 Python…</p>';try{const response=await fetch('/api/run',{method:'POST',signal:aborter.signal,headers:{'Content-Type':'application/json','X-Lab-Token':config.token},body:JSON.stringify({code:$('editor').value,task:wasFree?null:task().id})});const r=await response.json();if(!response.ok)throw Error(r.error||'运行服务出错');const el=$('result-content');el.replaceChildren();if(r.stdout){const p=document.createElement('pre');p.className='output-text';p.textContent=r.stdout;el.append(p)}if(r.error){const p=document.createElement('pre');p.className='output-text output-error';p.textContent=r.error;el.append(p)}for(const c of r.checks||[]){const block=document.createElement('div');block.className=`check ${c.passed?'':'fail'}`;block.innerHTML=`<span>${c.passed?'✓':'○'}</span><div>${esc(c.name)}${!c.passed?`<small>${esc(c.message)}</small>`:''}</div>`;el.append(block)}for(const src of r.images||[]){const img=document.createElement('img');img.src='data:image/png;base64,'+src;img.alt='本次 Python 运行生成的图表';img.className='result-figure';el.append(img)}if(r.files?.length){const wrap=document.createElement('div');wrap.className='result-files';for(const f of r.files){const a=document.createElement('a');a.href='data:application/octet-stream;base64,'+f.data;a.download=f.name;a.textContent='下载 '+f.name;wrap.append(a)}el.append(wrap)}const passed=!wasFree&&!r.error&&r.checks?.length&&r.checks.every(x=>x.passed);if(passed){state.passed[runKey]={at:new Date().toISOString(),withSolution:!!state.seen[runKey]};save();progress();$('task-tabs').querySelectorAll('button')[state.task].classList.add('passed');$('task-tabs').querySelectorAll('button')[state.task].querySelector('span').textContent='✓';const p=document.createElement('div');p.className='success-banner';p.textContent=state.seen[runKey]?'✓ 本题通过。看过解法的题，记得隔天独立重做。':'✓ 本题通过，做得好！试着解释每一步为什么这样写。';el.append(p)}if(!el.children.length)el.innerHTML='<p class="output-text">运行完成，没有输出。可以用 print() 查看变量。</p>';$('run-status').textContent=r.error?'需要调整':passed?'全部检查通过':wasFree?'运行完成':'检查完成'}catch(e){$('result-content').innerHTML=`<p class="output-text output-error">${e.name==='AbortError'?'运行已停止。':esc(e.message)+'。请确认本地服务正在运行。'}</p>`;$('run-status').textContent=e.name==='AbortError'?'已停止':'连接失败'}finally{busy=false;$('run-button').disabled=false;$('stop-button').hidden=true;aborter=null}}
$('editor').addEventListener('input',()=>{lines();remember()});$('editor').addEventListener('scroll',()=>{$('line-numbers').scrollTop=$('editor').scrollTop});$('editor').addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='Enter'){e.preventDefault();run()}else if(e.key==='Tab'){e.preventDefault();const a=e.target,start=a.selectionStart,end=a.selectionEnd;a.setRangeText('    ',start,end,'end');lines();remember()}else if(e.key==='Enter'){e.preventDefault();const a=e.target,start=a.selectionStart,prefix=a.value.slice(0,start).split('\n').pop(),indent=(prefix.match(/^ */)||[''])[0]+(prefix.trimEnd().endsWith(':')?'    ':'');a.setRangeText('\n'+indent,start,a.selectionEnd,'end');lines();remember()}});
$('run-button').onclick=run;$('stop-button').onclick=()=>{aborter?.abort();fetch('/api/stop',{method:'POST',headers:{'X-Lab-Token':config.token}}).catch(()=>{})};
$('hint-button').onclick=()=>{const t=task();state.hints[t.id]=Math.min((state.hints[t.id]||0)+1,t.hints.length);renderHints();save()};$('solution-details').addEventListener('toggle',()=>{if($('solution-details').open&&!free){state.seen[task().id]=true;save()}});
$('reset-code').onclick=()=>{if(busy)return;if(!confirm('将当前代码恢复为初始模板？已通过记录会保留。'))return;delete state.codes[key()];if(!free){delete state.hints[key()];delete state.seen[key()];}save();render();toast('已恢复初始代码')};
$('free-button').onclick=()=>{if(busy)return toast('请先停止当前运行');remember();free=true;render()};$('next-task').onclick=async()=>{if(busy)return toast('请先停止当前运行');if(state.day===6&&state.task===2){remember();clearTimeout(saveTimer);await persist();location.href='/';}else navigate(state.task===2?state.day+1:state.day,(state.task+1)%3)};
$('learn-button').onclick=()=>{$('notes-title').textContent=free?'自由练习说明':day().title;$('notes-content').innerHTML=free?'<p>NumPy、Pandas、Matplotlib 和 scikit-learn 已安装。变量不会跨次运行保留，请在同一份代码中导入库、定义数据和执行操作。</p><p>内置数据文件：<code>scores.csv</code> 用于第 3–6 天，<code>review.csv</code> 用于第 7 天。运行生成的 CSV 和文本文件可以从结果区下载。</p>':day().notes;$('notes-dialog').showModal()};$('close-notes').onclick=()=>$('notes-dialog').close();$('notes-dialog').addEventListener('click',e=>{if(e.target===$('notes-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
function download(name,content,type='text/plain'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('download-code').onclick=()=>download($('file-name').textContent,$('editor').value);$('backup').onclick=()=>{remember();download('ioai-lab-backup.json',JSON.stringify(state,null,2),'application/json');toast('学习备份已导出')};
function validateState(v){if(!v||typeof v!=='object'||Array.isArray(v))throw Error('备份格式不正确');const validIds=new Set(['free',...allWeeks.flatMap(w=>w.days.flatMap(d=>d.tasks.map(t=>t.id)))]);const cleaned={schemaVersion:2,week:v.week===2?2:1,positions:{},codes:{},passed:{},hints:{},seen:{},day:Number.isInteger(v.day)&&v.day>=0&&v.day<7?v.day:0,task:Number.isInteger(v.task)&&v.task>=0&&v.task<3?v.task:0};for(const field of ['codes','passed','hints','seen'])for(const [id,value]of Object.entries(v[field]||{})){if(!validIds.has(id))continue;if(field==='codes'&&typeof value==='string'&&value.length<=40000)cleaned.codes[id]=value;if(field==='passed'&&value)cleaned.passed[id]=value;if(field==='seen')cleaned.seen[id]=!!value;if(field==='hints'&&Number.isInteger(value))cleaned.hints[id]=Math.max(0,Math.min(2,value))}for(const week of ['1','2']){const pos=v.positions?.[week];if(pos&&Number.isInteger(pos.day)&&pos.day>=0&&pos.day<7&&Number.isInteger(pos.task)&&pos.task>=0&&pos.task<3)cleaned.positions[week]={day:pos.day,task:pos.task};}if(!cleaned.positions[cleaned.week])cleaned.positions[cleaned.week]={day:cleaned.day,task:cleaned.task};return cleaned}
$('import').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2000000)throw Error('备份文件过大');const v=validateState(JSON.parse(await f.text()));if(busy)throw Error('请先停止当前运行');if(confirm('用这份备份替换当前代码和学习进度？')){state=v;curriculum=allWeeks.find(w=>w.id===state.week);free=false;weekHeading();await persist();render();toast('已恢复学习进度')}}catch(error){toast(error.message)}finally{e.target.value=''}};
async function init(){try{
const responses=await Promise.all([fetch('/api/config',{cache:'no-store'}),fetch('/curriculum.json',{cache:'no-store'}),fetch('/week2.json',{cache:'no-store'}),fetch('/api/state',{cache:'no-store'})]);
if(responses.some(r=>!r.ok))throw Error('本地服务不可用');
const [cfg,week1,week2,saved]=await Promise.all(responses.map(r=>r.json()));config=cfg;
week1.id=1;week1.title='建立数据直觉';week1.description='数组、表格与可视化。把数据处理的基础练扎实。';week2.id=2;
allWeeks=[week1,week2];
if(saved&&Object.keys(saved).length)state=validateState(saved);else try{const local=JSON.parse(localStorage.getItem('ioai-week1'));if(local)state=validateState(local)}catch{}
const params=new URLSearchParams(location.search),wanted=params.get('week')==='2'?2:1;
const position=state.positions[wanted]||{day:0,task:0};state.week=wanted;state.day=position.day;state.task=position.task;
const requestedDay=Number(params.get('day')),requestedTask=Number(params.get('task'));
if(Number.isInteger(requestedDay)&&requestedDay>=1&&requestedDay<=7){state.day=requestedDay-1;state.task=0;}
if(Number.isInteger(requestedTask)&&requestedTask>=1&&requestedTask<=3)state.task=requestedTask-1;
free=params.get('free')==='1';curriculum=allWeeks.find(w=>w.id===wanted);weekHeading();render();
document.querySelectorAll('a[data-leave]').forEach(a=>a.addEventListener('click',async e=>{if(e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();if(busy)return toast('请先停止当前运行');remember();clearTimeout(saveTimer);await persist();location.href=a.href;}));
if(document.modelContext?.registerTool){try{
document.modelContext.registerTool({name:'read_learning_progress',description:'读取两周练习进度和当前题目。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:async()=>({week:state.week,completed:Object.keys(state.passed),current:free?'free':task().id})});
document.modelContext.registerTool({name:'open_practice_day',description:'打开本周指定学习日的第一题，不运行代码，也不标记完成。',inputSchema:{type:'object',properties:{day:{type:'integer',minimum:1,maximum:7}},required:['day'],additionalProperties:false},execute:async input=>{if(!Number.isInteger(input.day)||input.day<1||input.day>7||busy)throw Error('无效日期或代码正在运行');navigate(input.day-1,0);return{week:state.week,day:input.day,task:task().id}}});}catch{}}
}catch(e){$('run-status').textContent='启动失败';$('result-content').innerHTML='<p class="output-error">请重新双击启动脚本打开网页。页面需要本地 Python 服务。</p>';console.error(e)}}
init();
